insert into public.projects (id, title, slug, category_id, description, location, year, area_sqft, cover_image_url, images, featured) values
  ('0b0b0b0b-0000-4000-8000-000000000001', 'Lakeview Duplex', 'lakeview-duplex', '0c0c0c0c-0000-4000-8000-000000000001', 'A double-height living volume opens to a lake-facing terrace. Warm oak joinery, honed stone and layered lighting keep a large family home calm and intimate.', 'Bashundhara, Dhaka', 2025, 3400, null, '{}'::text[], true),
  ('0b0b0b0b-0000-4000-8000-000000000002', 'Courtyard Villa', 'courtyard-villa', '0c0c0c0c-0000-4000-8000-000000000001', 'Rooms wrap around a planted courtyard that pulls light and cross-breezes through the house — a modern take on the traditional Bengali uthan.', 'Khulshi, Chattogram', 2024, 4200, null, '{}'::text[], true),
  ('0b0b0b0b-0000-4000-8000-000000000003', 'Minimal Apartment', 'minimal-apartment', '0c0c0c0c-0000-4000-8000-000000000001', 'A compact flat re-planned around hidden storage and a single continuous material palette, so 1,450 sq ft reads as generous and uncluttered.', 'Dhanmondi, Dhaka', 2025, 1450, null, '{}'::text[], false),
  ('0b0b0b0b-0000-4000-8000-000000000004', 'Atelier Office', 'atelier-office', '0c0c0c0c-0000-4000-8000-000000000002', 'A creative agency''s headquarters: open studio floors, acoustic timber baffles and a double-sided library that doubles as a meeting space.', 'Gulshan, Dhaka', 2025, 6800, null, '{}'::text[], true),
  ('0b0b0b0b-0000-4000-8000-000000000005', 'Brand Flagship Store', 'flagship-store', '0c0c0c0c-0000-4000-8000-000000000002', 'A fashion flagship with a sculptural arched entrance, backlit display niches and a tonal palette that lets the product take centre stage.', 'Agrabad, Chattogram', 2024, 2900, null, '{}'::text[], false),
  ('0b0b0b0b-0000-4000-8000-000000000006', 'Co-working Hub', 'coworking-hub', '0c0c0c0c-0000-4000-8000-000000000002', 'Flexible work zones, phone booths and a sunlit café, designed for acoustics first and finished with durable, easy-care surfaces.', 'Uttara, Dhaka', 2023, 5200, null, '{}'::text[], false),
  ('0b0b0b0b-0000-4000-8000-000000000007', 'Boutique Hotel Lobby', 'boutique-hotel-lobby', '0c0c0c0c-0000-4000-8000-000000000003', 'A lobby that welcomes guests with tea-garden greens, hand-finished plaster and a statement brass reception desk.', 'Zindabazar, Sylhet', 2025, 3100, null, '{}'::text[], true),
  ('0b0b0b0b-0000-4000-8000-000000000008', 'Rooftop Restaurant', 'rooftop-restaurant', '0c0c0c0c-0000-4000-8000-000000000003', 'An all-weather rooftop dining space with a retractable canopy, warm festoon lighting and a skyline-facing open kitchen.', 'Banani, Dhaka', 2024, 4600, null, '{}'::text[], false),
  ('0b0b0b0b-0000-4000-8000-000000000009', 'Riverside Resort Suites', 'riverside-suites', '0c0c0c0c-0000-4000-8000-000000000003', 'Twelve river-view suites using local brick, cane and bamboo detailing, planned for passive cooling and low energy use.', 'Barishal', 2023, 7800, null, '{}'::text[], false)
insert into public.services (id, title, slug, summary, description, image_url, features, sort_order) values
  ('05e5e5e5-0000-4000-8000-000000000001', 'Interior Design', 'interior-design', 'Rooms that feel like you — planned down to the last switch and curtain rail.', 'We design interiors around the way you actually live and work. Every project starts with a conversation about routines, budget and taste, then moves through layout, materials, lighting and furniture — with 3D visuals so you can see the result before a single wall is touched.
insert into public.products (id, name, slug, description, category_id, price_bdt, stock, images, is_published) values
  ('0a0a0a0a-0000-4000-8000-000000000001', 'Brass Arc Floor Lamp', 'brass-arc-floor-lamp', 'A sweeping brushed-brass arc with a marble base and a linen-finish shade. Reaches over a sofa or reading chair without needing a ceiling point. E27 fitting, 2 m cable with inline switch.', '0c0c0c0c-0000-4000-8000-000000000011', 18500, 6, '{}'::text[], true),
  ('0a0a0a0a-0000-4000-8000-000000000002', 'Walnut Cantilever Coffee Table', 'walnut-cantilever-coffee-table', 'A solid walnut top floats on a slim powder-coated steel cantilever frame. Hand-oiled finish, 110 × 55 cm, built to order in our partner workshop.', '0c0c0c0c-0000-4000-8000-000000000012', 32000, 3, '{}'::text[], true),
  ('0a0a0a0a-0000-4000-8000-000000000003', 'Minimal Pendant Light Set (3 pcs)', 'minimal-pendant-light-set', 'Three opal-glass globe pendants on adjustable fabric cords. Ideal over a dining table or kitchen island; bulbs not included.', '0c0c0c0c-0000-4000-8000-000000000011', 12400, 10, '{}'::text[], true),
  ('0a0a0a0a-0000-4000-8000-000000000004', 'Handwoven Jute Area Rug, 5 × 8 ft', 'handwoven-jute-rug', 'Natural jute, hand-woven by artisans in a herringbone pattern. Adds texture and warmth to living rooms and bedrooms. Spot-clean only.', '0c0c0c0c-0000-4000-8000-000000000013', 14900, 8, '{}'::text[], true),
  ('0a0a0a0a-0000-4000-8000-000000000005', 'Fluted Wood Wall Panel (per panel)', 'fluted-wood-wall-panel', 'Pre-finished fluted oak-veneer panel, 2400 × 600 mm. Mounts on a simple batten frame — a quick way to add depth to feature walls and TV units.', '0c0c0c0c-0000-4000-8000-000000000014', 4800, 40, '{}'::text[], true),
  ('0a0a0a0a-0000-4000-8000-000000000006', 'Architect''s Scale Ruler & Drafting Set', 'architects-scale-ruler-set', 'Triangular architect''s scale (1:20–1:500), 30 cm engineer''s rule, compass, circle template and eraser shield — a complete desk-side drafting kit.', '0c0c0c0c-0000-4000-8000-000000000015', 3600, 15, '{}'::text[], true),
  ('0a0a0a0a-0000-4000-8000-000000000007', 'Terrazzo Tray & Planter Set', 'terrazzo-tray-planter-set', 'A hand-cast terrazzo tray with two matching planters in warm greys and soft yellow chips. Drainage holes included in the planters.', '0c0c0c0c-0000-4000-8000-000000000013', 6200, 12, '{}'::text[], true),
  ('0a0a0a0a-0000-4000-8000-000000000008', 'Architectural Model Kit — "Courtyard House"', 'courtyard-house-model-kit', 'A laser-cut 1:100 model kit of a courtyard house in birch plywood and card. A satisfying build for students, architects and design lovers; no glue gun required.', '0c0c0c0c-0000-4000-8000-000000000015', 9500, 5, '{}'::text[], true)
insert into public.testimonials (id, name, role, location, quote, rating, avatar_url, is_published, sort_order) values
  ('0d0d0d0d-0000-4000-8000-000000000001', 'Apartment owner', 'Homeowner', 'Dhanmondi, Dhaka', 'They turned a cramped flat into a calm, bright home. The 3D walkthrough meant there were no surprises on site — what we approved is exactly what we got.', 5, null, true, 1),
  ('0d0d0d0d-0000-4000-8000-000000000002', 'Agency founder', 'Office fit-out', 'Gulshan, Dhaka', 'Clear budgets, weekly updates and a team that actually showed up every day. Our office opened on the date we were promised.', 4.5, null, true, 2),
  ('0d0d0d0d-0000-4000-8000-000000000003', 'Villa owner', 'Residential', 'Khulshi, Chattogram', 'They understood how the building should breathe in our climate. The courtyard changed how the whole family lives.', 5, null, true, 3)
